import sys; sys.path.insert(0,'tools/seed')
from lib import A
A("tarot-la-gi","Tarot là gì? Nguồn gốc, cấu trúc 78 lá và cách dùng","tarot","Tarot là bộ bài 78 lá gồm Ẩn chính và Ẩn phụ. Tìm hiểu nguồn gốc, bốn bộ, và cách dùng để suy ngẫm.",
"""<h2>Tarot là gì?</h2><p>Tarot là bộ bài 78 lá, ban đầu xuất hiện ở Bắc Ý vào thế kỷ 15 như một trò chơi bài. Từ thế kỷ 18 – 19, các nhóm huyền học gắn cho bộ bài hệ biểu tượng và công dụng bói toán, từ đó tarot phổ biến như ngày nay.</p>
<h2>Cấu trúc bộ bài</h2><ul><li><strong>Bộ Ẩn chính (Major Arcana):</strong> 22 lá, từ 0 The Fool đến 21 The World, đại diện các chủ đề lớn trong đời.</li><li><strong>Bộ Ẩn phụ (Minor Arcana):</strong> 56 lá chia bốn bộ Gậy (Wands), Cốc (Cups), Kiếm (Swords), Tiền (Pentacles), mỗi bộ 14 lá gồm số 1 đến 10 và bốn lá hình người.</li></ul>
<h2>Tarot dùng để làm gì?</h2><p>Người dùng hiện đại thường xem tarot như công cụ tự vấn: rút bài để đặt câu hỏi, nhìn tình huống từ góc khác. Tarot không thể đảm bảo dự đoán tương lai, nên đừng dùng nó để quyết định chuyện sức khỏe, pháp lý hay tài chính lớn.</p>
<h2>Thử ngay</h2><ul><li><a href="/tarot-hom-nay">Tarot hôm nay</a>: rút một lá cho ngày mới.</li><li><a href="/trai-bai-3-la/tinh-yeu">Trải bài 3 lá</a>: quá khứ – hiện tại – tương lai.</li><li><a href="/tarot-yes-no">Tarot Yes/No</a>: câu trả lời nhanh.</li></ul>
<h2>Câu hỏi thường gặp</h2><h3>Cần bộ bài riêng không?</h3><p>Không bắt buộc; trên web có thể rút bài trực tuyến để tham khảo.</p><h3>Tarot có chính xác không?</h3><p>Nên xem là tham khảo và gợi ý suy nghĩ, không phải kết luận.</p>""")
A("22-la-bai-an-chinh-tarot","22 lá bài Ẩn chính trong Tarot: hành trình từ The Fool đến The World","tarot","Tổng quan bộ Ẩn chính (Major Arcana) 22 lá và ý tưởng hành trình của Chàng Khờ.",
"""<h2>Bộ Ẩn chính là gì?</h2><p>Major Arcana gồm 22 lá đánh số từ 0 đến 21. Đây là những lá có hình tượng mạnh nhất, thường được hiểu là các chặng lớn hoặc bài học quan trọng trong cuộc sống.</p>
<h2>Hành trình của Chàng Khờ</h2><p>Nhiều tác giả đọc chuỗi 22 lá như một hành trình: bắt đầu với The Fool (số 0), người khởi hành đầy tin tưởng, đi qua nhiều gặp gỡ và thử thách rồi kết thúc ở The World (số 21), sự trọn vẹn.</p>
<h2>Danh sách các lá</h2><p>The Fool, The Magician, The High Priestess, The Empress, The Emperor, The Hierophant, The Lovers, The Chariot, Strength, The Hermit, Wheel of Fortune, Justice, The Hanged Man, Death, Temperance, The Devil, The Tower, The Star, The Moon, The Sun, Judgement, The World.</p>
<h2>Cách đọc khi xuất hiện</h2><p>Khi một trải bài có nhiều lá Ẩn chính, người đọc thường cho rằng chủ đề đang xét mang tầm quan trọng lớn. Lá Death thường chỉ sự kết thúc để chuyển đổi, không phải điềm chết chóc theo nghĩa đen.</p>
<p>Xem từng lá chi tiết tại <a href="/tarot">trang Tarot</a>.</p>
<h2>Câu hỏi thường gặp</h2><h3>Lá The Fool nghĩa là gì?</h3><p>Thường là khởi đầu mới, tự do và sự tin tưởng; mặt ngược gợi ý thiếu cân nhắc.</p>""")
A("cach-rut-bai-tarot-cho-nguoi-moi","Cách rút bài Tarot cho người mới: 5 bước đơn giản","tarot","Hướng dẫn đặt câu hỏi, xáo bài, rút bài và đọc ý nghĩa dành cho người mới bắt đầu.",
"""<h2>Chuẩn bị</h2><p>Chọn lúc yên tĩnh, đặt câu hỏi rõ ràng. Câu hỏi mở như "Tôi nên chú ý điều gì ở công việc lúc này?" thường hữu ích hơn câu hỏi bắt buộc có hoặc không.</p>
<h2>5 bước rút bài</h2><ul><li><strong>Bước 1:</strong> Xác định câu hỏi và viết ra nếu muốn.</li><li><strong>Bước 2:</strong> Xáo bài, tập trung vào câu hỏi.</li><li><strong>Bước 3:</strong> Chọn số lá: một lá cho ngày mới, ba lá cho tình huống.</li><li><strong>Bước 4:</strong> Lật bài theo thứ tự.</li><li><strong>Bước 5:</strong> Đọc từ khóa của từng lá, ghép lại thành câu chuyện.</li></ul>
<h2>Cách đọc trải bài 3 lá</h2><p>Phổ biến nhất là Quá khứ – Hiện tại – Tương lai, hoặc Tình huống – Thử thách – Lời khuyên. Hãy đọc lá cạnh nhau, không đọc riêng lẻ.</p>
<h2>Mẹo cho người mới</h2><ul><li>Ghi nhật ký rút bài để so sánh với thực tế.</li><li>Đừng rút đi rút lại một câu hỏi.</li><li>Đừng dùng tarot cho quyết định về sức khỏe, pháp lý, đầu tư lớn.</li></ul>
<p>Thử ngay <a href="/rut-la-tarot">Rút lá tarot</a> hoặc <a href="/tarot-hom-nay">Tarot hôm nay</a>.</p>
<h2>Câu hỏi thường gặp</h2><h3>Rút ra lá không hiểu thì sao?</h3><p>Đọc phần ý nghĩa từng lá và nhìn vào hình ảnh, thường sẽ có gợi ý.</p>""")
A("tarot-xuoi-nguoc","Lá bài Tarot xuôi và ngược: cách hiểu ý nghĩa","tarot","Phân biệt lá xuôi và lá ngược, các cách hiểu lá ngược và cách đọc để không bị hoang mang.",
"""<h2>Xuôi và ngược khác gì?</h2><p>Khi rút, nếu lá bài hiện đúng chiều thì gọi là xuôi (upright), nếu đầu dưới lên thì là ngược (reversed). Mỗi lá thường có hai lớp ý nghĩa tương ứng.</p>
<h2>Các cách hiểu lá ngược</h2><ul><li><strong>Ý nghĩa đối lập:</strong> ví dụ lá mang tính tích cực chuyển thành trở ngại.</li><li><strong>Năng lượng bị chặn hoặc yếu:</strong> điều đó có đó nhưng chưa phát huy.</li><li><strong>Hướng nội:</strong> vấn đề nằm bên trong bản thân hơn là bên ngoài.</li></ul>
<h2>Có bắt buộc dùng lá ngược không?</h2><p>Không. Nhiều người đọc tarot chỉ dùng lá xuôi cho đơn giản. Nếu mới bắt đầu, bạn có thể chưa cần lá ngược.</p>
<h2>Lưu ý khi đọc</h2><p>Lá ngược không có nghĩa là điềm xấu. Nó thường là lời nhắc xem xét lại điều gì đó, nhất là khi kết hợp với các lá xung quanh.</p>
<p>Trên TriMenh, mỗi lá tại <a href="/tarot">trang Tarot</a> đều có phần nghĩa xuôi và nghĩa ngược.</p>
<h2>Câu hỏi thường gặp</h2><h3>Lá ngược có phải lúc nào cũng xấu?</h3><p>Không, có khi lá ngược lại gợi ý thoát khỏi một tình huống nặng nề.</p>""")
A("24-tiet-khi","24 tiết khí là gì? Danh sách và ý nghĩa","lich-ngay-tot","24 tiết khí chia năm theo vị trí Mặt Trời, liệt kê tên và vai trò trong nông nghiệp và lịch pháp.",
"""<h2>Tiết khí là gì?</h2><p>Tiết khí là 24 mốc chia năm theo vị trí của Mặt Trời trên hoàng đạo, mỗi mốc cách nhau khoảng 15 ngày. Nó xuất phát từ nông lịch Á Đông và phản ánh thay đổi của thời tiết, mùa vụ.</p>
<h2>Danh sách 24 tiết khí</h2><p>Lập xuân, Vũ thủy, Kinh trập, Xuân phân, Thanh minh, Cốc vũ; Lập hạ, Tiểu mãn, Mang chủng, Hạ chí, Tiểu thử, Đại thử; Lập thu, Xử thử, Bạch lộ, Thu phân, Hàn lộ, Sương giáng; Lập đông, Tiểu tuyết, Đại tuyết, Đông chí, Tiểu hàn, Đại hàn.</p>
<h2>Vai trò trong lịch pháp</h2><p>Tiết khí dùng để xác định tháng trong lịch âm dương, tính tháng nhuận (tháng không có trung khí) và tính Trực của ngày. Vì vậy các lịch vạn niên luôn ghi tiết khí.</p>
<h2>Trong đời sống</h2><p>Nông dân xưa dựa vào tiết khí để gieo trồng. Ngày nay nhiều người dùng tiết khí để điều chỉnh ăn uống, dưỡng sinh theo mùa. Hãy xem thêm trang <a href="/tiet-khi">Tiết khí</a>.</p>
<h2>Câu hỏi thường gặp</h2><h3>Tiết khí cố định theo dương lịch không?</h3><p>Gần như cố định, lệch nhau một hai ngày giữa các năm vì tính theo vị trí Mặt Trời.</p>""")
A("ngay-khong-minh-xuat-hanh","Ngày Khổng Minh: 6 ngày xuất hành Đại An, Tốc Hỷ, Xích Khẩu…","lich-ngay-tot","Giải thích sáu ngày theo phép Khổng Minh, cách tính và cách tham khảo khi xuất hành, cầu tài.",
"""<h2>Phép Khổng Minh là gì?</h2><p>Khổng Minh (hay Lục diệu) là phép xem ngày xuất hành quen thuộc trong dân gian, gắn với tên Gia Cát Lượng thời Tam Quốc, dù nguồn gốc chưa được kiểm chứng chắc chắn. Mỗi ngày thuộc một trong sáu trạng thái lặp lại.</p>
<h2>Sáu ngày</h2><ul><li><strong>Đại An:</strong> yên ổn, thuận cho việc cần bền vững.</li><li><strong>Lưu Niên:</strong> chậm trễ, nên kiên nhẫn.</li><li><strong>Tốc Hỷ:</strong> tin vui đến nhanh, thường dùng cho cầu tài, gặp gỡ.</li><li><strong>Xích Khẩu:</strong> dễ tranh cãi, thị phi.</li><li><strong>Tiểu Cát:</strong> thuận lợi vừa phải.</li><li><strong>Không Vong:</strong> trống rỗng, thường khuyên tránh việc lớn.</li></ul>
<h2>Cách dùng</h2><p>Phép này thường dùng khi xuất hành, đi xa, gặp đối tác. Cách tính dựa trên ngày và tháng âm lịch nên cần đổi sang âm lịch trước. Công cụ <a href="/xem-ngay-tot">Xem ngày tốt</a> hiển thị ngày Khổng Minh sẵn cho từng ngày.</p>
<h2>Kết hợp với giờ</h2><p>Trong ngày, bạn có thể xem thêm giờ tốt qua công cụ <a href="/gio-hoang-dao">Giờ Hoàng đạo</a>.</p>
<h2>Câu hỏi thường gặp</h2><h3>Ngày Không Vong có nên đi xa?</h3><p>Theo quan niệm xưa nên cân nhắc; nhiều người chuyển sang giờ tốt hoặc dời lịch nếu có thể.</p>""")
A("chon-ngay-khai-truong","Chọn ngày khai trương: các tiêu chí cần cân nhắc","lich-ngay-tot","Gợi ý tiêu chí chọn ngày khai trương theo Hoàng đạo, Trực, tuổi chủ và giờ tốt, kèm lưu ý thực tế.",
"""<h2>Vì sao nhiều người chọn ngày khai trương?</h2><p>Khai trương là mốc mở đầu của việc kinh doanh nên được nhiều người coi trọng, mong buổi đầu suôn sẻ. Chọn ngày cũng là dịp chốt kế hoạch cho cả nhóm.</p>
<h2>Tiêu chí thường dùng</h2><ul><li><strong>Ngày Hoàng đạo:</strong> ưu tiên hơn ngày Hắc đạo.</li><li><strong>Trực:</strong> Khai, Thành, Định thường được ưa chuộng; Phá thường bị tránh.</li><li><strong>Tuổi chủ cửa hàng:</strong> tránh ngày có chi xung tuổi.</li><li><strong>Giờ Hoàng đạo:</strong> chọn giờ mở cửa hoặc làm lễ.</li><li><strong>Phong tục:</strong> nhiều nơi tránh ngày mùng 5, 14, 23 âm lịch theo quan niệm dân gian.</li></ul>
<h2>Lưu ý thực tế</h2><p>Hãy chọn ngày thuận tiện cho khách: cuối tuần hoặc ngày thị trường đông. Chuẩn bị hàng hóa, nhân sự, khuyến mãi cũng quan trọng không kém ngày đẹp.</p>
<p>Xem danh sách ngày đẹp sắp tới tại <a href="/xem-ngay/khai-truong">Xem ngày khai trương</a>.</p>
<h2>Câu hỏi thường gặp</h2><h3>Có cần xem ngày nếu mở cửa hàng online?</h3><p>Không bắt buộc; một số người vẫn chọn ngày đẹp để ra mắt trang cho yên tâm.</p>""")
A("chon-ngay-cuoi-hoi","Chọn ngày cưới hỏi: các bước và tiêu chí phổ biến","lich-ngay-tot","Cách chọn ngày cưới hỏi: xem tuổi, ngày Hoàng đạo, giờ rước dâu và lưu ý khi sắp xếp thực tế.",
"""<h2>Ngày cưới hỏi quan trọng thế nào?</h2><p>Trong văn hóa Việt, ngày cưới thường được hai gia đình bàn bạc kỹ. Việc chọn ngày vừa thể hiện sự trân trọng, vừa giúp mọi người thống nhất kế hoạch.</p>
<h2>Các bước chọn ngày</h2><ul><li><strong>Bước 1:</strong> Xác định khoảng thời gian phù hợp với cả hai nhà.</li><li><strong>Bước 2:</strong> Kiểm tra năm cưới, tránh năm phạm kim lâu, hoang ốc nếu gia đình quan tâm.</li><li><strong>Bước 3:</strong> Ưu tiên ngày Hoàng đạo, Trực Thành, Định, Mãn tùy tài liệu.</li><li><strong>Bước 4:</strong> Tránh ngày xung tuổi cô dâu chú rể.</li><li><strong>Bước 5:</strong> Chọn giờ đón dâu, giờ làm lễ theo giờ Hoàng đạo.</li></ul>
<h2>Cân nhắc thực tế</h2><p>Khách mời, địa điểm, ngân sách và thời tiết thường quyết định lịch cuối cùng. Một ngày đẹp mà quá bất tiện đôi khi không đáng. Nếu hai ngày đều ổn, hãy chọn ngày thuận tiện hơn.</p>
<p>Xem gợi ý ở <a href="/xem-ngay/cuoi-hoi">Xem ngày cưới hỏi</a> và kiểm tra tuổi tại <a href="/xem-tuoi-ket-hon">Xem tuổi kết hôn</a>.</p>
<h2>Câu hỏi thường gặp</h2><h3>Có nên cưới trong tháng nhuận?</h3><p>Quan niệm khác nhau tùy vùng; nhiều gia đình tránh, nhưng không có quy định bắt buộc.</p>""")
A("tu-vi-12-con-giap-cach-doc","Tử vi 12 con giáp: cách đọc cho đúng","tu-vi","Hiểu đúng tử vi hằng ngày, hằng tuần, hằng tháng theo con giáp và cách dùng làm tham khảo.",
"""<h2>Tử vi theo con giáp là gì?</h2><p>Tử vi theo con giáp là dạng tham khảo ngắn dựa vào năm sinh, chia người ta thành 12 nhóm. Nó khác với lá số Tử vi Đẩu số cá nhân, vốn cần giờ sinh và tính toán chi tiết.</p>
<h2>Cách đọc hiệu quả</h2><ul><li>Chọn đúng con giáp theo năm sinh âm lịch (người sinh trước Tết tính theo năm trước).</li><li>Đọc xu hướng chung, đừng xem như dự báo chắc chắn.</li><li>Xem cùng thông tin ngày, tháng để lên kế hoạch.</li></ul>
<h2>Hằng ngày, tuần, tháng</h2><p>TriMenh có <a href="/tu-vi-hom-nay">tử vi hôm nay</a>, <a href="/tu-vi-tuan">tử vi tuần</a> và <a href="/tu-vi-thang">tử vi tháng</a>. Mỗi mục dùng cùng một cách tính nên kết quả nhất quán cho mọi người cùng con giáp.</p>
<h2>Giới hạn cần biết</h2><p>Vì chỉ dựa vào con giáp nên không phân biệt được hàng triệu người cùng tuổi. Hãy dùng làm gợi ý nhẹ nhàng, không dựa vào đó để ra quyết định lớn.</p>
<h2>Câu hỏi thường gặp</h2><h3>Tử vi con giáp có thay thế lá số không?</h3><p>Không. Lá số cá nhân chi tiết hơn vì dựa trên ngày giờ sinh đầy đủ.</p>""")
